import React, {
  useEffect,
  useState,
} from 'react';

import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiGrid,
  FiCheckCircle,
  FiXCircle,
  FiImage,
  FiHash,
  FiUploadCloud,
  FiX,
  FiGlobe,
} from 'react-icons/fi';

import api from '../../services/api';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

import {
  useLanguage,
} from '../../contexts/LanguageContext';


const initialForm = {
  title_en: '',
  title_km: '',
  description_en: '',
  description_km: '',
  icon: '',
  image: null,
  is_active: true,
  order: 0,
};


const AdminServices = () => {

  const {
    t,
    language,
  } = useLanguage();


  const [services, setServices] = useState([]);

  const [loading, setLoading] = useState(true);

  const [modalOpen, setModalOpen] = useState(false);

  const [
    editingService,
    setEditingService,
  ] = useState(null);

  const [
    submitting,
    setSubmitting,
  ] = useState(false);

  const [
    imagePreview,
    setImagePreview,
  ] = useState(null);

  const [
    imageRemoved,
    setImageRemoved,
  ] = useState(false);

  const [
    formData,
    setFormData,
  ] = useState({
    ...initialForm,
  });


  // ==========================================
  // LANGUAGE
  // ==========================================

  const isKhmer =
    language === 'km' ||
    language === 'kh';


  const titleField =
    isKhmer
      ? 'title_km'
      : 'title_en';


  const descriptionField =
    isKhmer
      ? 'description_km'
      : 'description_en';


  const tr = (
    key,
    englishFallback,
    khmerFallback
  ) => {

    const value = t(key);

    if (
      value &&
      value !== key
    ) {
      return value;
    }

    return isKhmer
      ? khmerFallback
      : englishFallback;
  };


  // ==========================================
  // GET LOCALIZED TITLE
  // ==========================================

  const getServiceTitle = (
    service
  ) => {

    if (!service) {
      return '-';
    }

    if (isKhmer) {

      return (
        service.title_km ||
        service.title_en ||
        service.title ||
        '-'
      );
    }

    return (
      service.title_en ||
      service.title_km ||
      service.title ||
      '-'
    );
  };


  // ==========================================
  // GET LOCALIZED DESCRIPTION
  // ==========================================

  const getServiceDescription = (
    service
  ) => {

    if (!service) {
      return '';
    }

    if (isKhmer) {

      return (
        service.description_km ||
        service.description_en ||
        service.description ||
        ''
      );
    }

    return (
      service.description_en ||
      service.description_km ||
      service.description ||
      ''
    );
  };


  // ==========================================
  // IMAGE PATH
  // ==========================================

  const getImagePath = (
    service
  ) => {

    if (!service) {
      return null;
    }

    return (
      service.image ||
      service.image_url ||
      null
    );
  };


  // ==========================================
  // FETCH ON LOAD
  // ==========================================

  useEffect(() => {

    fetchServices();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  // ==========================================
  // CLEAN BLOB URL
  // ==========================================

  useEffect(() => {

    return () => {

      if (
        imagePreview &&
        imagePreview.startsWith('blob:')
      ) {

        URL.revokeObjectURL(
          imagePreview
        );
      }
    };

  }, [imagePreview]);


  // ==========================================
  // FETCH SERVICES
  // ==========================================

  const fetchServices = async () => {

    try {

      setLoading(true);

      const response =
        await api.get(
          '/api/services/all'
        );

      setServices(
        Array.isArray(
          response.data
        )
          ? response.data
          : []
      );

    } catch (error) {

      console.error(
        'Fetch services error:',
        error
      );

      toast.error(
        error.response?.data?.detail ||
        tr(
          'services.loadFailed',
          'Failed to load services.',
          'មិនអាចទាញយកទិន្នន័យសេវាកម្មបានទេ។'
        )
      );

    } finally {

      setLoading(false);
    }
  };


  // ==========================================
  // RESET FORM
  // ==========================================

  const resetForm = () => {

    setEditingService(null);

    setFormData({
      ...initialForm,
    });

    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {

      URL.revokeObjectURL(
        imagePreview
      );
    }

    setImagePreview(null);

    setImageRemoved(false);
  };


  // ==========================================
  // ADD
  // ==========================================

  const handleAdd = () => {

    resetForm();

    setModalOpen(true);
  };


  // ==========================================
  // CLOSE MODAL
  // ==========================================

  const handleCloseModal = () => {

    if (submitting) {
      return;
    }

    setModalOpen(false);

    resetForm();
  };


  // ==========================================
  // SHARED INPUT CHANGE
  // ==========================================

  const handleInputChange = (
    event
  ) => {

    const {
      name,
      value,
      type,
      checked,
    } = event.target;

    setFormData(
      (previous) => ({
        ...previous,

        [name]:
          type === 'checkbox'
            ? checked
            : value,
      })
    );
  };


  // ==========================================
  // LOCALIZED INPUT CHANGE
  // ==========================================

  const handleLocalizedChange = (
    field,
    value
  ) => {

    const fieldName =
      isKhmer
        ? `${field}_km`
        : `${field}_en`;

    setFormData(
      (previous) => ({
        ...previous,
        [fieldName]: value,
      })
    );
  };


  // ==========================================
  // IMAGE CHANGE
  // ==========================================

  const handleImageChange = (
    event
  ) => {

    const file =
      event.target.files?.[0];

    if (!file) {
      return;
    }

    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];

    if (
      !allowedTypes.includes(
        file.type
      )
    ) {

      toast.error(
        tr(
          'services.invalidImage',
          'Please select a JPG, JPEG, PNG or WEBP image.',
          'សូមជ្រើសរើសរូបភាពប្រភេទ JPG, JPEG, PNG ឬ WEBP។'
        )
      );

      event.target.value = '';

      return;
    }

    const maxSize =
      5 * 1024 * 1024;

    if (
      file.size > maxSize
    ) {

      toast.error(
        tr(
          'services.imageTooLarge',
          'Image must be 5 MB or smaller.',
          'រូបភាពត្រូវមានទំហំ 5 MB ឬតូចជាងនេះ។'
        )
      );

      event.target.value = '';

      return;
    }

    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {

      URL.revokeObjectURL(
        imagePreview
      );
    }

    const previewUrl =
      URL.createObjectURL(file);

    setFormData(
      (previous) => ({
        ...previous,
        image: file,
      })
    );

    setImagePreview(
      previewUrl
    );

    setImageRemoved(false);
  };


  // ==========================================
  // REMOVE IMAGE
  // ==========================================

  const handleRemoveImage = () => {

    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {

      URL.revokeObjectURL(
        imagePreview
      );
    }

    setFormData(
      (previous) => ({
        ...previous,
        image: null,
      })
    );

    setImagePreview(null);

    setImageRemoved(true);
  };


  // ==========================================
  // SUBMIT
  // ==========================================

  const handleSubmit = async (
    event
  ) => {

    event.preventDefault();


    // Validate current language only
    if (
      !formData[
        titleField
      ]?.trim()
    ) {

      toast.error(
        isKhmer
          ? 'សូមបញ្ចូលចំណងជើងសេវាកម្ម។'
          : 'Please enter the service title.'
      );

      return;
    }


    try {

      setSubmitting(true);

      const data =
        new FormData();


      // English
      data.append(
        'title_en',
        formData.title_en.trim()
      );

      data.append(
        'description_en',
        formData.description_en.trim()
      );


      // Khmer
      data.append(
        'title_km',
        formData.title_km.trim()
      );

      data.append(
        'description_km',
        formData.description_km.trim()
      );


      // Shared
      data.append(
        'icon',
        formData.icon.trim()
      );

      data.append(
        'is_active',
        String(
          formData.is_active
        )
      );

      data.append(
        'order',
        String(
          Number(
            formData.order
          ) || 0
        )
      );


      if (
        formData.image instanceof File
      ) {

        data.append(
          'image',
          formData.image
        );
      }


      if (
        editingService &&
        imageRemoved &&
        !(
          formData.image instanceof File
        )
      ) {

        data.append(
          'remove_image',
          'true'
        );
      }


      if (editingService) {

        await api.put(
          `/api/services/${editingService.id}`,
          data
        );

        toast.success(
          tr(
            'services.updatedSuccess',
            'Service updated successfully.',
            'បានកែប្រែសេវាកម្មដោយជោគជ័យ។'
          )
        );

      } else {

        await api.post(
          '/api/services/',
          data
        );

        toast.success(
          tr(
            'services.createdSuccess',
            'Service created successfully.',
            'បានបង្កើតសេវាកម្មដោយជោគជ័យ។'
          )
        );
      }


      setModalOpen(false);

      resetForm();

      await fetchServices();

    } catch (error) {

      console.error(
        'Service operation error:',
        error
      );

      console.error(
        'Backend response:',
        error.response?.data
      );

      let message =
        tr(
          'services.operationFailed',
          'Service operation failed.',
          'ប្រតិបត្តិការសេវាកម្មមិនបានជោគជ័យ។'
        );

      const detail =
        error.response?.data?.detail;

      if (
        typeof detail === 'string'
      ) {

        message = detail;

      } else if (
        Array.isArray(detail)
      ) {

        message = detail
          .map(
            (item) => {

              const field =
                item?.loc?.[
                  item.loc.length - 1
                ];

              return (
                `${field || 'Field'}: ${
                  item?.msg ||
                  tr(
                    'common.validationError',
                    'Validation error',
                    'ទិន្នន័យមិនត្រឹមត្រូវ'
                  )
                }`
              );
            }
          )
          .join(', ');
      }

      toast.error(message);

    } finally {

      setSubmitting(false);
    }
  };


  // ==========================================
  // EDIT
  // ==========================================

  const handleEdit = (
    service
  ) => {

    setEditingService(
      service
    );

    setFormData({

      title_en:
        service.title_en ||
        service.title ||
        '',

      title_km:
        service.title_km ||
        '',

      description_en:
        service.description_en ||
        service.description ||
        '',

      description_km:
        service.description_km ||
        '',

      icon:
        service.icon || '',

      image: null,

      is_active:
        service.is_active !==
        undefined
          ? Boolean(
              service.is_active
            )
          : true,

      order:
        Number(
          service.order
        ) || 0,
    });

    setImagePreview(
      getImagePath(service)
    );

    setImageRemoved(false);

    setModalOpen(true);
  };


  // ==========================================
  // DELETE
  // ==========================================

  const handleDelete = async (
    id
  ) => {

    const confirmed =
      window.confirm(
        tr(
          'services.deleteConfirm',
          'Are you sure you want to delete this service?',
          'តើអ្នកប្រាកដថាចង់លុបសេវាកម្មនេះមែនទេ?'
        )
      );

    if (!confirmed) {
      return;
    }

    try {

      await api.delete(
        `/api/services/${id}`
      );

      toast.success(
        tr(
          'services.deletedSuccess',
          'Service deleted successfully.',
          'បានលុបសេវាកម្មដោយជោគជ័យ។'
        )
      );

      await fetchServices();

    } catch (error) {

      console.error(
        'Delete service error:',
        error
      );

      toast.error(
        error.response?.data?.detail ||
        tr(
          'services.deleteFailed',
          'Failed to delete service.',
          'មិនអាចលុបសេវាកម្មបានទេ។'
        )
      );
    }
  };


  // ==========================================
  // COUNTS
  // ==========================================

  const activeCount =
    services.filter(
      (service) =>
        service.is_active
    ).length;


  const inactiveCount =
    services.filter(
      (service) =>
        !service.is_active
    ).length;


  const imageCount =
    services.filter(
      (service) =>
        getImagePath(service)
    ).length;


  // ==========================================
  // TABLE COLUMNS
  // ==========================================

  const columns = [

    {
      key: 'icon',

      label:
        tr(
          'services.icon',
          'Icon',
          'រូបតំណាង'
        ),

      render: (value) => (

        <div
          className="
            w-10
            h-10
            bg-blue-50
            rounded-lg
            flex
            items-center
            justify-center
            text-xl
            border
            border-blue-200
          "
        >
          {value || '📌'}
        </div>
      ),
    },


    {
      key: 'title',

      label:
        tr(
          'services.service',
          'Service',
          'សេវាកម្ម'
        ),

      render: (
        value,
        row
      ) => {

        const title =
          getServiceTitle(
            row
          );

        return (

          <div
            className="
              max-w-[240px]
            "
          >

            <p
              className="
                text-sm
                font-bold
                text-blue-900
                truncate
              "
            >
              {
                title ||
                tr(
                  'services.untitled',
                  'Untitled',
                  'គ្មានចំណងជើង'
                )
              }
            </p>

          </div>
        );
      },
    },


    {
      key: 'description',

      label:
        tr(
          'services.description',
          'Description',
          'ការពិពណ៌នា'
        ),

      render: (
        value,
        row
      ) => {

        const description =
          getServiceDescription(
            row
          );

        return (

          <p
            className="
              text-sm
              text-blue-500
              max-w-[280px]
              truncate
            "
          >
            {
              description ||
              tr(
                'services.noDescription',
                'No description',
                'គ្មានការពិពណ៌នា'
              )
            }
          </p>
        );
      },
    },


    {
      key: 'order',

      label:
        tr(
          'services.order',
          'Order',
          'លំដាប់'
        ),

      render: (value) => (

        <div
          className="
            inline-flex
            items-center
            justify-center
            min-w-[36px]
            h-8
            px-2
            bg-blue-50
            text-blue-900
            rounded-lg
            text-xs
            font-bold
          "
        >
          {value ?? 0}
        </div>
      ),
    },


    {
      key: 'is_active',

      label:
        tr(
          'common.status',
          'Status',
          'ស្ថានភាព'
        ),

      render: (value) => (

        <span
          className={`
            inline-flex
            items-center
            gap-1.5
            px-2.5
            py-1.5
            rounded-full
            text-[11px]
            font-semibold

            ${
              value
                ? `
                  bg-blue-50
                  text-blue-700
                  border
                  border-blue-200
                `
                : `
                  bg-red-50
                  text-red-600
                  border
                  border-red-100
                `
            }
          `}
        >

          <span
            className={`
              w-1.5
              h-1.5
              rounded-full

              ${
                value
                  ? 'bg-blue-500'
                  : 'bg-red-500'
              }
            `}
          />

          {
            value
              ? tr(
                  'common.active',
                  'Active',
                  'សកម្ម'
                )
              : tr(
                  'common.inactive',
                  'Inactive',
                  'អសកម្ម'
                )
          }

        </span>
      ),
    },


    {
      key: 'actions',

      label:
        tr(
          'common.actions',
          'Actions',
          'សកម្មភាព'
        ),

      render: (
        value,
        row
      ) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          <button
            type="button"

            onClick={() =>
              handleEdit(
                row
              )
            }

            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              bg-blue-50
              text-blue-900
              rounded-lg
              hover:bg-blue-900
              hover:text-white
              transition
            "

            title={
              tr(
                'services.editService',
                'Edit Service',
                'កែប្រែសេវាកម្ម'
              )
            }
          >

            <FiEdit2
              size={14}
            />

          </button>


          <button
            type="button"

            onClick={() =>
              handleDelete(
                row.id
              )
            }

            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              bg-red-50
              text-red-600
              rounded-lg
              hover:bg-red-600
              hover:text-white
              transition
            "

            title={
              tr(
                'services.deleteService',
                'Delete Service',
                'លុបសេវាកម្ម'
              )
            }
          >

            <FiTrash2
              size={14}
            />

          </button>

        </div>
      ),
    },
  ];


  // ==========================================
  // RENDER
  // ==========================================

  return (

    <div
      className={
        isKhmer
          ? 'w-full font-khmer'
          : 'w-full font-english'
      }
    >


      {/* ======================================
          HEADER
      ======================================= */}

      <div
        className="
          flex
          flex-col
          sm:flex-row
          sm:items-center
          sm:justify-between
          gap-4
          mb-6
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-10
              h-10
              bg-blue-900
              text-white
              rounded-xl
              flex
              items-center
              justify-center
              shadow-sm
            "
          >

            <FiGrid
              size={18}
            />

          </div>


          <div>

            <h1
              className="
                text-xl
                md:text-2xl
                font-bold
                text-blue-900
              "
            >
              {
                tr(
                  'services.title',
                  'Services Management',
                  'គ្រប់គ្រងសេវាកម្ម'
                )
              }
            </h1>


            <p
              className="
                text-xs
                md:text-sm
                text-blue-400
                mt-1
              "
            >
              {
                tr(
                  'services.subtitle',
                  'Manage services and service content',
                  'គ្រប់គ្រងសេវាកម្ម និងមាតិកាសេវាកម្ម'
                )
              }
            </p>

          </div>

        </div>


        <button
          type="button"

          onClick={
            handleAdd
          }

          className="
            h-10
            px-4
            inline-flex
            items-center
            justify-center
            gap-2
            bg-red-600
            text-white
            rounded-lg
            text-sm
            font-semibold
            shadow-sm
            hover:bg-red-700
            hover:shadow-md
            transition-all
          "
        >

          <FiPlus
            size={17}
          />

          {
            tr(
              'services.addService',
              'Add Service',
              'បន្ថែមសេវាកម្ម'
            )
          }

        </button>

      </div>


      {/* ======================================
          SUMMARY
      ======================================= */}

      <div
        className="
          grid
          grid-cols-2
          xl:grid-cols-4
          gap-3
          mb-6
        "
      >

        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {
                  tr(
                    'services.totalServices',
                    'Total Services',
                    'សេវាកម្មសរុប'
                  )
                }
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-900
                  mt-1
                "
              >
                {services.length}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-blue-50
                text-blue-900
                rounded-lg
                flex
                items-center
                justify-center
              "
            >

              <FiGrid
                size={18}
              />

            </div>

          </div>

        </div>


        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {
                  tr(
                    'common.active',
                    'Active',
                    'សកម្ម'
                  )
                }
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-600
                  mt-1
                "
              >
                {activeCount}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-blue-50
                text-blue-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >

              <FiCheckCircle
                size={18}
              />

            </div>

          </div>

        </div>


        <div
          className="
            bg-white
            border
            border-red-100
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {
                  tr(
                    'common.inactive',
                    'Inactive',
                    'អសកម្ម'
                  )
                }
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-red-600
                  mt-1
                "
              >
                {inactiveCount}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-red-50
                text-red-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >

              <FiXCircle
                size={18}
              />

            </div>

          </div>

        </div>


        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {
                  tr(
                    'services.withImages',
                    'With Images',
                    'មានរូបភាព'
                  )
                }
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-red-600
                  mt-1
                "
              >
                {imageCount}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-red-50
                text-red-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >

              <FiImage
                size={18}
              />

            </div>

          </div>

        </div>

      </div>


      {/* ======================================
          TABLE
      ======================================= */}

      <AdminCard
        className="
          border
          border-blue-200
          rounded-xl
          shadow-sm
          overflow-hidden
        "
      >

        <div
          className="
            px-5
            py-4
            border-b
            border-blue-200
          "
        >

          <h2
            className="
              text-sm
              font-bold
              text-blue-900
            "
          >
            {
              tr(
                'services.allServices',
                'All Services',
                'សេវាកម្មទាំងអស់'
              )
            }
          </h2>


          <p
            className="
              text-xs
              text-blue-300
              mt-1
            "
          >
            {services.length}{' '}

            {
              tr(
                'services.services',
                'services',
                'សេវាកម្ម'
              )
            }{' '}

            {
              tr(
                'services.found',
                'found',
                'ត្រូវបានរកឃើញ'
              )
            }
          </p>

        </div>


        <AdminTable
          columns={columns}
          data={services}
          loading={loading}
        />

      </AdminCard>


      {/* ======================================
          MODAL
      ======================================= */}

      <AdminModal
        isOpen={
          modalOpen
        }

        onClose={
          handleCloseModal
        }

        title={
          editingService
            ? tr(
                'services.editService',
                'Edit Service',
                'កែប្រែសេវាកម្ម'
              )
            : tr(
                'services.createService',
                'Create Service',
                'បង្កើតសេវាកម្ម'
              )
        }
      >

        <form
          onSubmit={
            handleSubmit
          }

          className={
            isKhmer
              ? 'font-khmer'
              : 'font-english'
          }
        >

          <div
            className="
              space-y-5
            "
          >


            {/* ==================================
                CURRENT LANGUAGE
            =================================== */}

            <div
              className="
                flex
                items-center
                gap-3
                px-4
                py-3
                bg-blue-50
                border
                border-blue-200
                rounded-xl
              "
            >

              <div
                className="
                  w-9
                  h-9
                  bg-white
                  text-blue-900
                  rounded-lg
                  border
                  border-blue-200
                  flex
                  items-center
                  justify-center
                "
              >

                <FiGlobe
                  size={17}
                />

              </div>


              <div>

                <p
                  className="
                    text-sm
                    font-bold
                    text-blue-900
                  "
                >
                  {
                    isKhmer
                      ? 'មាតិកាភាសាខ្មែរ'
                      : 'English Content'
                  }
                </p>


                <p
                  className="
                    text-[10px]
                    text-blue-400
                    mt-0.5
                  "
                >
                  {
                    isKhmer
                      ? 'អ្នកកំពុងកែសម្រួលមាតិកាភាសាខ្មែរ'
                      : 'You are editing the English content'
                  }
                </p>

              </div>

            </div>


            {/* ==================================
                TITLE
            =================================== */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >

                {
                  isKhmer
                    ? 'ចំណងជើងសេវាកម្ម'
                    : 'Service Title'
                }

                <span
                  className="
                    text-red-600
                  "
                >
                  {' '}*
                </span>

              </label>


              <input
                type="text"

                value={
                  formData[
                    titleField
                  ]
                }

                onChange={(event) =>
                  handleLocalizedChange(
                    'title',
                    event.target.value
                  )
                }

                placeholder={
                  isKhmer
                    ? 'បញ្ចូលចំណងជើងសេវាកម្ម'
                    : 'Enter service title'
                }

                className="
                  w-full
                  h-11
                  px-3.5
                  border
                  border-blue-200
                  rounded-lg
                  text-sm
                  text-blue-900
                  bg-white
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                  transition
                "

                required
              />

            </div>


            {/* ==================================
                DESCRIPTION
            =================================== */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >

                {
                  isKhmer
                    ? 'ការពិពណ៌នា'
                    : 'Description'
                }

              </label>


              <textarea
                value={
                  formData[
                    descriptionField
                  ]
                }

                onChange={(event) =>
                  handleLocalizedChange(
                    'description',
                    event.target.value
                  )
                }

                rows={4}

                placeholder={
                  isKhmer
                    ? 'បញ្ចូលការពិពណ៌នាសេវាកម្ម'
                    : 'Enter service description'
                }

                className="
                  w-full
                  px-3.5
                  py-3
                  border
                  border-blue-200
                  rounded-lg
                  text-sm
                  text-blue-900
                  bg-white
                  resize-none
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                  transition
                "
              />

            </div>


            {/* ==================================
                ICON + ORDER
            =================================== */}

            <div
              className="
                grid
                grid-cols-1
                md:grid-cols-2
                gap-4
                w-full
                min-w-0
              "
            >

              <div
                className="
                  min-w-0
                "
              >

                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-blue-900
                    mb-1.5
                  "
                >
                  {
                    tr(
                      'services.icon',
                      'Icon',
                      'រូបតំណាង'
                    )
                  }
                </label>


                <div
                  className="
                    relative
                    w-full
                    min-w-0
                  "
                >

                  <div
                    className="
                      absolute
                      left-1.5
                      top-1/2
                      -translate-y-1/2
                      w-8
                      h-8
                      bg-blue-50
                      rounded-md
                      flex
                      items-center
                      justify-center
                      text-lg
                      pointer-events-none
                    "
                  >
                    {
                      formData.icon ||
                      '📌'
                    }
                  </div>


                  <input
                    type="text"

                    name="icon"

                    value={
                      formData.icon
                    }

                    onChange={
                      handleInputChange
                    }

                    placeholder="📚"

                    maxLength={10}

                    className="
                      block
                      w-full
                      min-w-0
                      h-11
                      pl-12
                      pr-3
                      border
                      border-blue-200
                      rounded-lg
                      text-sm
                      text-blue-900
                      bg-white
                      outline-none
                      overflow-hidden
                      text-ellipsis
                      whitespace-nowrap
                      focus:border-blue-900
                      focus:ring-2
                      focus:ring-blue-900/10
                    "
                  />

                </div>


                <p
                  className="
                    text-[10px]
                    text-blue-300
                    mt-1.5
                  "
                >
                  {
                    tr(
                      'services.iconExample',
                      'Example: 📚, 💻, 🎓',
                      'ឧទាហរណ៍៖ 📚, 💻, 🎓'
                    )
                  }
                </p>

              </div>


              <div
                className="
                  min-w-0
                "
              >

                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-blue-900
                    mb-1.5
                  "
                >
                  {
                    tr(
                      'services.displayOrder',
                      'Display Order',
                      'លំដាប់បង្ហាញ'
                    )
                  }
                </label>


                <div
                  className="
                    relative
                  "
                >

                  <FiHash
                    className="
                      absolute
                      left-3.5
                      top-1/2
                      -translate-y-1/2
                      text-blue-300
                      pointer-events-none
                    "
                  />


                  <input
                    type="number"

                    name="order"

                    min="0"

                    value={
                      formData.order
                    }

                    onChange={
                      handleInputChange
                    }

                    className="
                      w-full
                      h-11
                      pl-10
                      pr-3.5
                      border
                      border-blue-200
                      rounded-lg
                      text-sm
                      text-blue-900
                      bg-white
                      outline-none
                      focus:border-blue-900
                      focus:ring-2
                      focus:ring-blue-900/10
                    "
                  />

                </div>


                <p
                  className="
                    text-[10px]
                    text-blue-300
                    mt-1.5
                  "
                >
                  {
                    tr(
                      'services.orderHelp',
                      'Lower numbers appear first.',
                      'លេខតូចជាងនឹងបង្ហាញមុន។'
                    )
                  }
                </p>

              </div>

            </div>


            {/* ==================================
                IMAGE
            =================================== */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >
                {
                  tr(
                    'services.serviceImage',
                    'Service Image',
                    'រូបភាពសេវាកម្ម'
                  )
                }
              </label>


              {
                !imagePreview ? (

                  <label
                    className="
                      w-full
                      min-h-[150px]
                      border-2
                      border-dashed
                      border-blue-200
                      rounded-xl
                      flex
                      flex-col
                      items-center
                      justify-center
                      cursor-pointer
                      bg-blue-50
                      hover:border-blue-400
                      transition-all
                    "
                  >

                    <div
                      className="
                        w-12
                        h-12
                        bg-white
                        text-blue-900
                        rounded-xl
                        flex
                        items-center
                        justify-center
                        mb-3
                        border
                        border-blue-200
                      "
                    >

                      <FiUploadCloud
                        size={24}
                      />

                    </div>


                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >
                      {
                        tr(
                          'services.uploadImage',
                          'Upload Image',
                          'បញ្ចូលរូបភាព'
                        )
                      }
                    </p>


                    <p
                      className="
                        text-xs
                        text-blue-300
                        mt-1
                      "
                    >
                      JPG, JPEG, PNG, WEBP
                    </p>


                    <p
                      className="
                        text-[10px]
                        text-blue-300
                        mt-1
                      "
                    >
                      {
                        tr(
                          'services.maxFileSize',
                          'Maximum file size: 5 MB',
                          'ទំហំឯកសារអតិបរមា៖ 5 MB'
                        )
                      }
                    </p>


                    <input
                      type="file"

                      accept="
                        image/jpeg,
                        image/jpg,
                        image/png,
                        image/webp
                      "

                      onChange={
                        handleImageChange
                      }

                      className="
                        hidden
                      "
                    />

                  </label>

                ) : (

                  <div
                    className="
                      relative
                      w-full
                      h-[220px]
                      bg-blue-50
                      rounded-xl
                      overflow-hidden
                      border
                      border-blue-200
                      group
                    "
                  >

                    <img
                      src={
                        imagePreview
                      }

                      alt={
                        tr(
                          'services.imagePreview',
                          'Service preview',
                          'ការមើលរូបភាពសេវាកម្ម'
                        )
                      }

                      className="
                        w-full
                        h-full
                        object-cover
                      "
                    />


                    <div
                      className="
                        absolute
                        inset-0
                        bg-black/30
                        opacity-0
                        group-hover:opacity-100
                        transition
                      "
                    />


                    <label
                      className="
                        absolute
                        left-1/2
                        top-1/2
                        -translate-x-1/2
                        -translate-y-1/2
                        h-10
                        px-4
                        bg-white
                        text-blue-900
                        rounded-lg
                        text-sm
                        font-semibold
                        flex
                        items-center
                        justify-center
                        gap-2
                        cursor-pointer
                        opacity-0
                        group-hover:opacity-100
                        shadow
                        transition
                      "
                    >

                      <FiUploadCloud
                        size={16}
                      />


                      {
                        tr(
                          'services.changeImage',
                          'Change Image',
                          'ប្ដូររូបភាព'
                        )
                      }


                      <input
                        type="file"

                        accept="
                          image/jpeg,
                          image/jpg,
                          image/png,
                          image/webp
                        "

                        onChange={
                          handleImageChange
                        }

                        className="
                          hidden
                        "
                      />

                    </label>


                    <button
                      type="button"

                      onClick={
                        handleRemoveImage
                      }

                      className="
                        absolute
                        top-3
                        right-3
                        w-9
                        h-9
                        bg-red-600
                        text-white
                        rounded-lg
                        flex
                        items-center
                        justify-center
                        hover:bg-red-700
                        shadow
                        transition
                      "

                      title={
                        tr(
                          'services.removeImage',
                          'Remove Image',
                          'លុបរូបភាព'
                        )
                      }
                    >

                      <FiX
                        size={18}
                      />

                    </button>

                  </div>
                )
              }

            </div>


            {/* ==================================
                ACTIVE
            =================================== */}

            <label
              className={`
                flex
                items-center
                justify-between
                gap-3
                p-4
                border
                rounded-xl
                cursor-pointer
                transition-all

                ${
                  formData.is_active
                    ? `
                      border-blue-200
                      bg-blue-50/60
                    `
                    : `
                      border-blue-200
                      bg-white
                    `
                }
              `}
            >

              <div
                className="
                  flex
                  items-center
                  gap-3
                "
              >

                <div
                  className={`
                    w-9
                    h-9
                    rounded-lg
                    flex
                    items-center
                    justify-center

                    ${
                      formData.is_active
                        ? `
                          bg-blue-100
                          text-blue-600
                        `
                        : `
                          bg-blue-50
                          text-blue-300
                        `
                    }
                  `}
                >

                  {
                    formData.is_active ? (

                      <FiCheckCircle
                        size={17}
                      />

                    ) : (

                      <FiXCircle
                        size={17}
                      />
                    )
                  }

                </div>


                <div>

                  <p
                    className="
                      text-sm
                      font-semibold
                      text-blue-900
                    "
                  >
                    {
                      tr(
                        'services.activeService',
                        'Active Service',
                        'សេវាកម្មសកម្ម'
                      )
                    }
                  </p>


                  <p
                    className="
                      text-[10px]
                      text-blue-300
                      mt-0.5
                    "
                  >
                    {
                      tr(
                        'services.showOnWebsite',
                        'Show this service on the website',
                        'បង្ហាញសេវាកម្មនេះនៅលើគេហទំព័រ'
                      )
                    }
                  </p>

                </div>

              </div>


              <div
                className={`
                  relative
                  w-11
                  h-6
                  rounded-full
                  transition

                  ${
                    formData.is_active
                      ? 'bg-blue-500'
                      : 'bg-blue-200'
                  }
                `}
              >

                <div
                  className={`
                    absolute
                    top-1
                    w-4
                    h-4
                    bg-white
                    rounded-full
                    shadow
                    transition-all

                    ${
                      formData.is_active
                        ? 'left-6'
                        : 'left-1'
                    }
                  `}
                />

              </div>


              <input
                type="checkbox"

                name="is_active"

                checked={
                  formData.is_active
                }

                onChange={
                  handleInputChange
                }

                className="
                  hidden
                "
              />

            </label>

          </div>


          {/* ==================================
              BUTTONS
          =================================== */}

          <div
            className="
              mt-6
              pt-4
              border-t
              border-blue-200
              flex
              flex-col-reverse
              sm:flex-row
              sm:items-center
              sm:justify-end
              gap-3
            "
          >

            <button
              type="button"

              onClick={
                handleCloseModal
              }

              disabled={
                submitting
              }

              className="
                h-10
                px-4
                bg-white
                border
                border-blue-200
                text-blue-400
                rounded-lg
                text-sm
                font-semibold
                hover:bg-blue-50
                disabled:opacity-50
                disabled:cursor-not-allowed
                transition
              "
            >
              {
                tr(
                  'common.cancel',
                  'Cancel',
                  'បោះបង់'
                )
              }
            </button>


            <button
              type="submit"

              disabled={
                submitting
              }

              className="
                min-w-[130px]
                h-10
                px-5
                bg-red-600
                text-white
                rounded-lg
                text-sm
                font-semibold
                hover:bg-red-700
                disabled:opacity-50
                disabled:cursor-not-allowed
                transition
              "
            >

              {
                submitting
                  ? editingService
                    ? tr(
                        'services.updating',
                        'Updating...',
                        'កំពុងកែប្រែ...'
                      )
                    : tr(
                        'services.creating',
                        'Creating...',
                        'កំពុងបង្កើត...'
                      )
                  : editingService
                    ? tr(
                        'services.updateService',
                        'Update Service',
                        'រក្សាទុកការកែប្រែ'
                      )
                    : tr(
                        'services.createService',
                        'Create Service',
                        'បង្កើតសេវាកម្ម'
                      )
              }

            </button>

          </div>

        </form>

      </AdminModal>

    </div>
  );
};


export default AdminServices;
